from taf.fdsw.rc.interfaces.FDSW20B.autoconnection import AutoConfiguration20B
from taf.fdsw.rc.schemas.FDSW21A.autoconnection import AutoConnection21A
from taf.fdsw.rc.schemas.FDSW21A.autoconnection_parameters_builder_21a import \
    AutoconnectionParametersBuilder21A


class AutoConfiguration21A(AutoConfiguration20B):
    param_builder = AutoconnectionParametersBuilder21A

    def __init__(self, client):
        super(AutoConfiguration20B, self).__init__(client)

    def get_autoconnection_parameters(self, timeout=10):
        autoconnection = self.autoconnection_parameters()
        autoconnection_parameters = AutoConnection21A.from_object_dict(data=autoconnection.data)
        return autoconnection_parameters.to_dict()

    @staticmethod
    def is_subset(dict1, dict2):
        """Check if dict1 is a subset of dict2"""
        result = False
        try:
            for key, value in dict1.items():
                if isinstance(value, dict):
                    result = AutoConfiguration21A.is_subset(value, dict2[key])
                    assert result
                else:
                    assert dict2[key] == value
                    result = True
        except (AssertionError, KeyError):
            result = False
        return result

    def enable_autoconnection_service(self, timeout=10):
        self._client.send(
            method='config.autoconnection.update',
            timeout=timeout,
            parameters={"pnpStatus": {"connection": {"mode": "Automatic"}}})

    def disable_autoconnection_service(self, timeout=10):
        self._client.send(
            method='config.autoconnection.update',
            timeout=timeout,
            parameters={"pnpStatus": {"connection": {"mode": "Manual"}}})
